          category: "gifts",
          type: "Home fragrance",
          price: "$52",
          oldPrice: "$64",
          badge: "Bundle save",
          imageClass: "",
          description: "Three bestselling fragrances in a giftable set.",
        },
      ];

      const grid = document.getElementById("productGrid");
      const chips = Array.from(document.querySelectorAll("[data-filter]"));

      function renderProducts(filter = "all") {
        const filtered = products.filter((product) => filter === "all" || product.category === filter);

        grid.innerHTML = filtered
          .map(
            (product) => `
              <article class="product-card" aria-label="${product.name}">
                <div class="product-card__image ${product.imageClass}">
                  <span class="product-card__badge">${product.badge}</span>
                </div>
                <div class="product-card__body">
                  <div class="product-card__meta">
                    <span>${product.type}</span>
                    <span>Top rated</span>
                  </div>
                  <h3>${product.name}</h3>
                  <p>${product.description}</p>
                  <div class="product-card__actions">
                    <div class="price">${product.price} <del>${product.oldPrice}</del></div>
                    <button class="card__cta" type="button">Add to bag</button>
                  </div>
                </div>
              </article>
            `
          )
          .join("");
      }

      chips.forEach((chip) => {
        chip.addEventListener("click", () => {
          chips.forEach((button) => button.setAttribute("aria-pressed", "false"));
          chip.setAttribute("aria-pressed", "true");
          renderProducts(chip.dataset.filter);
        });
      });

      function updateCountdown() {
        const target = new Date();
        target.setDate(target.getDate() + 3);
        target.setHours(12, 45, 10, 0);

        const now = new Date();
        const diff = Math.max(0, target - now);
        const totalSeconds = Math.floor(diff / 1000);
        const days = Math.floor(totalSeconds / 86400);
        const hours = Math.floor((totalSeconds % 86400) / 3600);
        const minutes = Math.floor((totalSeconds % 3600) / 60);
        const seconds = totalSeconds % 60;

        document.getElementById("days").textContent = String(days).padStart(2, "0");
        document.getElementById("hours").textContent = String(hours).padStart(2, "0");
        document.getElementById("minutes").textContent = String(minutes).padStart(2, "0");
        document.getElementById("seconds").textContent = String(seconds).padStart(2, "0");
      }

      renderProducts();
      updateCountdown();
      setInterval(updateCountdown, 1000);
    </script>
