      .floating-card--top {
        left: -1rem;
        top: 1.2rem;
      }

      .floating-card--bottom {
        right: -0.5rem;
        bottom: 1rem;
        min-width: 180px;
      }

      .floating-card strong {
        font-size: 1.05rem;
      }

      .floating-card span {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .section {
        padding: 2rem 0;
      }

      .section-header {
        margin-bottom: 1rem;
      }

      .section-header h2 {
        margin: 0;
