      .editorial-card__body {
        padding: 1.15rem;
      }

      .editorial-card p {
        margin: 0.45rem 0 0;
        color: var(--muted);
      }

      .promo {
        margin: 2rem 0 0;
        padding: 1.3rem 1.4rem;
        border-radius: var(--radius);
        background: linear-gradient(135deg, rgba(15, 118, 110, 0.12), rgba(15, 23, 42, 0.04));
        border: 1px solid var(--border);
