      .promo p {
        margin: 0.3rem 0 0;
        color: var(--muted);
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1.15fr 0.85fr;
        gap: 1rem;
      }

      .newsletter__panel {
        padding: 1.4rem;
        border-radius: var(--radius);
        background: rgba(255, 255, 255, 0.84);
        border: 1px solid var(--border);
      }

      .newsletter form {
        display: flex;
        gap: 0.75rem;
        margin-top: 1rem;
      }

      .newsletter input {
        flex: 1;
        min-width: 0;
        padding: 0.95rem 1rem;
        border-radius: 999px;
        border: 1px solid var(--border);
        background: white;
      }

      footer {
        padding: 1.6rem 0 2.2rem;
        color: var(--muted);
      }

      .footer {
        padding-top: 1rem;
        border-top: 1px solid var(--border);
        align-items: flex-start;
      }

      .footer nav ul {
        flex-wrap: wrap;
        justify-content: flex-end;
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        border: 0;
        white-space: nowrap;
      }

      @media (max-width: 960px) {
        nav ul {
          display: none;
        }

        .hero,
        .newsletter,
        .promo,
        .section-header,
        .footer {
          flex-direction: column;
          align-items: flex-start;
        }

        .hero {
          min-height: auto;
          padding-top: 1rem;
        }

        .hero__visual {
          width: 100%;
          min-height: 420px;
        }

        .product-card,
        .editorial-card,
        .deal--large,
        .deal--stack {
          grid-column: span 12;
        }

        .newsletter form {
          flex-direction: column;
        }
      }

      @media (max-width: 640px) {
        .topbar__inner {
          flex-direction: column;
          align-items: flex-start;
        }

        .hero__stats,
        .deal__timer {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .hero__content h1 {
          font-size: clamp(2.5rem, 15vw, 4.2rem);
        }

        .floating-card--top {
          left: 0;
        }

        .floating-card--bottom {
          right: 0;
        }
      }
    </style>
  </head>
  <body>
